type ModuleKey='home'|'doctor'|'patients'|'appointments'|'operations'|'visits'|'staff'|'users'|'finance'|'reports';
type Profile=any; type Row=Record<string,any>;
const nav:[ModuleKey,string,string][]=[['home','◫','لوحة التحكم'],['doctor','◉','Dashboard الطبيب'],['appointments','▦','المواعيد'],['patients','♙','ملفات المرضى'],['operations','✚','عمليات زراعة الشعر'],['visits','✚','سجل الزيارات'],['staff','♧','الأطباء والفريق'],['users','⚙','المستخدمون والصلاحيات'],['finance','▤','الحسابات'],['reports','▧','التقارير']];
const roleModules:Record<string,ModuleKey[]>={reception:['home','appointments','patients','operations','visits','staff'],doctor:['home','doctor','patients','visits'],hair_team:['home','doctor','patients','operations','staff'],finance:['home','finance','reports'],admin:nav.map(n=>n[0])};
const services=[{label:'كشف',kind:'consultation',fee:350},{label:'إعاده',kind:'follow_up',fee:200},{label:'ميزوسربي',kind:'mesotherapy',fee:800},{label:'بلازما',kind:'plasma',fee:700},{label:'بوتكس',kind:'botox',fee:0},{label:'تقشير بارد',kind:'cold_peel',fee:0},{label:'سكين بوستر',kind:'skin_booster',fee:0}];
