const money=(v:any)=>`${Number(v||0).toLocaleString('en-US')} ج.م`;
const dateTime=(v:string)=>v?new Date(v).toLocaleString('ar-EG',{dateStyle:'medium',timeStyle:'short'}):'—';
const asLocalInput=(date=new Date())=>{const d=new Date(date.getTime()-date.getTimezoneOffset()*60000);return d.toISOString().slice(0,16)};
export default function Dashboard(){
 const router=useRouter();const [profile,setProfile]=useState<Profile>(null);const [moduleKey,setModuleKey]=useState<ModuleKey>('home');const [branchId,setBranchId]=useState('');const [branches,setBranches]=useState<Row[]>([]);const [rows,setRows]=useState<Row[]>([]);const [patients,setPatients]=useState<Row[]>([]);const [appointmentPatients,setAppointmentPatients]=useState<Row[]>([]);const [staff,setStaff]=useState<Row[]>([]);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [search,setSearch]=useState('');const [modal,setModal]=useState('');const [form,setForm]=useState<Row>({});const [selectedPatient,setSelectedPatient]=useState<Row|null>(null);const [patientPrivate,setPatientPrivate]=useState<Row|null>(null);const [patientVisits,setPatientVisits]=useState<Row[]>([]);const [patientImages,setPatientImages]=useState<Row[]>([]);const [counts,setCounts]=useState<Row>({});const [weekOffset,setWeekOffset]=useState(0);const [reportPeriod,setReportPeriod]=useState<'day'|'week'|'month'>('week');const [doctorScheduleRows,setDoctorScheduleRows]=useState<Row[]>([]);
 const isAdmin=profile?.role==='admin';const isReception=profile?.role==='reception';const roleNav:ModuleKey[]=roleModules[profile?.role||'']||['home'];const savedModules=Array.isArray(profile?.permissions?.modules)?profile.permissions.modules as ModuleKey[]:null;const visibleNav=nav.filter(n=>roleNav.includes(n[0])&&(isAdmin||!savedModules||savedModules.includes(n[0])));const branch=branches.find(b=>b.id===branchId);const org=profile?.organization_id;const targetDoctorId=profile?.role==='doctor'?profile.id:staff.find(s=>/عبد ?الرحمن|abdelrahman/i.test(s.full_name||'')&&s.role==='doctor')?.id;const currentModule=nav.find(n=>n[0]===moduleKey)?.[2]||'';
 const loadModule=useCallback(async()=>{if(!supabase||!profile||!org||!branchId)return;setBusy(true);setError('');let table='patients';if(moduleKey==='appointments'||moduleKey==='doctor')table='appointments';if(moduleKey==='operations')table='operations';if(moduleKey==='visits')table='visits';if(moduleKey==='staff')table='staff_schedules';if(moduleKey==='users')table='profiles';if(moduleKey==='finance')table='financial_transactions';if(moduleKey==='reports')table='financial_transactions';if(moduleKey==='home'){setBusy(false);return;}if(moduleKey==='users'&&!isAdmin){setError('إدارة المستخدمين متاحة للـ Admin فقط.');setRows([]);setBusy(false);return;}let q=supabase.from(table).select('*').limit(250);if(table!=='profiles')q=q.eq('branch_id',branchId);else q=q.eq('active',true);if(moduleKey==='staff')q=q.eq('branch_id',branchId);if(moduleKey==='appointments'||moduleKey==='doctor')q=q.order('scheduled_at',{ascending:true});else if(moduleKey==='operations')q=q.order('scheduled_at',{ascending:false});else if(moduleKey==='visits')q=q.order('visited_at',{ascending:false});else if(moduleKey==='finance'||moduleKey==='reports')q=q.order('paid_at',{ascending:false});else if(moduleKey==='staff')q=q.order('weekday',{ascending:true});else q=q.order('created_at',{ascending:false});const r=await q;if(r.error){setError(r.error.message);setRows([]);}else setRows(r.data||[]);setBusy(false);},[moduleKey,profile,org,branchId]);
 useEffect(()=>{let cancelled=false;async function init(){if(!supabase){router.replace('/login');return;}const {data:{user}}=await supabase.auth.getUser();if(!user){router.replace('/login');return;}const p=await supabase.from('profiles').select('*').eq('id',user.id).maybeSingle();if(p.error||!p.data){setError('الملف الشخصي غير مهيأ. يحتاج Admin إنشاء Profile وربطه بالمؤسسة والفرع.');return;}if(cancelled)return;setProfile(p.data);const b=await supabase.from('branches').select('*').eq('organization_id',p.data.organization_id);if(cancelled)return;setBranches(b.data||[]);setBranchId(p.data.role==='admin'?'':p.data.branch_id||b.data?.[0]?.id||'');if(p.data.role==='admin'&&b.data?.[0]?.id)setBranchId(b.data[0].id);const pt=await supabase.from('patients').select('id,full_name,patient_number,age,created_at').eq('branch_id',p.data.role==='admin'?(b.data?.[0]?.id||''):p.data.branch_id).limit(1000).order('created_at',{ascending:false});setPatients(pt.data||[]);const ap=await supabase.from('appointments').select('patient_id').eq('branch_id',p.data.role==='admin'?(b.data?.[0]?.id||''):p.data.branch_id);const eligible=new Set((ap.data||[]).map((x:Row)=>x.patient_id));setAppointmentPatients((pt.data||[]).filter((x:Row)=>eligible.has(x.id)));const st=await supabase.from('profiles').select('id,full_name,role,branch_id,active').eq('organization_id',p.data.organization_id).eq('active',true);setStaff(st.data||[]);}init();return()=>{cancelled=true}},[router]);
 useEffect(()=>{loadModule()},[loadModule]);
 useEffect(()=>{if(!supabase||!branchId)return;async function loadBranchPatients(){const pt=await supabase!.from('patients').select('id,full_name,patient_number,age,created_at').eq('branch_id',branchId).limit(1000).order('created_at',{ascending:false});setPatients(pt.data||[]);const ap=await supabase!.from('appointments').select('patient_id').eq('branch_id',branchId);const eligible=new Set((ap.data||[]).map((x:Row)=>x.patient_id));setAppointmentPatients((pt.data||[]).filter((x:Row)=>eligible.has(x.id)));}loadBranchPatients();},[branchId]);
 useEffect(()=>{if(!supabase||!branchId||moduleKey!=='doctor')return;async function getDoctorSchedules(){const q=supabase!.from('staff_schedules').select('*').eq('branch_id',branchId).eq('active',true);if(profile?.role==='doctor')q.eq('staff_profile_id',profile.id);const r=await q;setDoctorScheduleRows(r.data||[]);}getDoctorSchedules();},[moduleKey,branchId,profile]);
 useEffect(()=>{if(!supabase||!profile||!branchId||moduleKey!=='home')return;async function getCounts(){const pairs=await Promise.all(['patients','appointments','operations','visits'].map(t=>supabase!.from(t).select('*',{count:'exact',head:true}).eq('branch_id',branchId)));setCounts({patients:pairs[0].count||0,appointments:pairs[1].count||0,operations:pairs[2].count||0,visits:pairs[3].count||0});}getCounts()},[moduleKey,profile,branchId]);
 const filtered=useMemo(()=>rows.filter(r=>!search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase())),[rows,search]);
 const resetForm=()=>setForm({});
 const openModal=(type:string,row?:Row)=>{setForm(type==='user'?{role:'reception',branch_id:branches[0]?.id||'',permissions:{modules:[...roleModules.reception]}}:{});setModal(type);setSelectedPatient(row||null);};
 async function refresh(){await loadModule();if(supabase&&org){const pt=await supabase.from('patients').select('id,full_name,patient_number,age,created_at').eq('branch_id',branchId).limit(1000).order('created_at',{ascending:false});setPatients(pt.data||[]);}}
 async function logout(){await supabase?.auth.signOut();router.replace('/login');}
 async function savePatient(e:any){e.preventDefault();if(!supabase||!org||!branchId)return;setBusy(true);const payload={organization_id:org,branch_id:branchId,full_name:String(form.full_name||'').trim(),age:form.age?Number(form.age):null,gender:form.gender||null,acquisition_source:form.acquisition_source||null,notes:form.notes||null,created_by:profile.id};const p=await supabase.from('patients').insert(payload).select('*').single();if(p.error){setError(p.error.message);setBusy(false);return;}if(form.phone||form.national_id||form.address){const pr=await supabase.from('patient_private_details').insert({patient_id:p.data.id,organization_id:org,branch_id:branchId,phone:form.phone||null,national_id:form.national_id||null,address:form.address||null});if(pr.error){setError('تم تسجيل المريض لكن تعذر حفظ بيانات التواصل: '+pr.error.message);setBusy(false);return;}}setModal('');setBusy(false);await refresh();}
 async function saveAppointment(e:any){e.preventDefault();if(!supabase||!org||!branchId)return;const patient=patients.find(p=>p.id===form.patient_id);const isNew=!patient;const patientName=String(isNew?form.patient_name:patient?.full_name||'').trim();if(!patientName){setError('أدخل اسم المريض أو اختر ملفًا مسجلًا');return;}const s=services.find(x=>x.label===form.service)||services[0];const manual=['بوتكس','تقشير بارد','سكين بوستر'].includes(s.label);const special=['ميزوسربي','بلازما'].includes(s.label);const mode=manual?'manual_price':special?(form.service_mode||'paid'):'paid';const fee=mode==='operation'?0:manual?Number(form.fee||0):s.fee;if(manual&&fee<=0){setError('أدخل سعر الخدمة');return;}setBusy(true);const scheduled=new Date(form.scheduled_at||asLocalInput()).toISOString();const appt={organization_id:org,branch_id:branchId,patient_id:patient?.id||null,patient_name:patientName,age:form.age?Number(form.age):patient?.age||null,kind:s.kind,scheduled_at:scheduled,fee,service_mode:mode,service_name:s.label,service_fee:fee,service_payment_mode:mode,arrival_source:form.arrival_source||null,flow:'booked',notes:form.notes||null,created_by:profile.id,doctor_id:form.doctor_id||null};const a=await supabase.from('appointments').insert(appt).select('*').single();if(a.error){setError(a.error.message);setBusy(false);return;}if(form.phone){const pp=await supabase.from('appointment_private_details').insert({appointment_id:a.data.id,phone:form.phone});if(pp.error)setError('تم حفظ الموعد لكن لم يتم حفظ رقم الهاتف: '+pp.error.message);}if(fee>0){const paid=await supabase.from('financial_transactions').insert({organization_id:org,branch_id:branchId,direction:'income',description:`رسوم موعد ${s.label} - ${patientName}`,amount:fee,payment_method:form.payment_method||'cash',patient_id:patient?.id||null,appointment_id:a.data.id,created_by:profile.id});if(paid.error)setError('تم حجز الموعد لكن تعذر تسجيل الإيراد: '+paid.error.message);}setModal('');setBusy(false);await refresh();}
 async function changeAppointment(row:Row,flow:string){if(!supabase)return;const allowed:Record<string,string>={booked:'arrived',arrived:'with_doctor',with_doctor:'completed'};if(allowed[row.flow]!==flow){setError('غير مسموح تخطي مرحلة أو الرجوع إلى مرحلة سابقة.');return;}const data:any={flow,updated_at:new Date().toISOString()};if(flow==='arrived')data.arrived_at=new Date().toISOString();if(flow==='with_doctor'){data.doctor_entered_at=new Date().toISOString();if(!row.patient_id){const patient=await supabase.from('patients').insert({organization_id:row.organization_id,branch_id:row.branch_id,full_name:row.patient_name,age:row.age||null,acquisition_source:row.arrival_source||null,created_by:profile.id}).select('*').single();if(patient.error){setError('تعذر تحويل الموعد إلى ملف مريض: '+patient.error.message);return;}data.patient_id=patient.data.id;const priv=await supabase.from('appointment_private_details').select('phone').eq('appointment_id',row.id).maybeSingle();if(priv.data?.phone){const saved=await supabase.from('patient_private_details').insert({patient_id:patient.data.id,organization_id:row.organization_id,branch_id:row.branch_id,phone:priv.data.phone});if(saved.error)setError('تم إنشاء الملف لكن لم يتم نقل الهاتف إلى بيانات المريض.');}}}if(flow==='completed')data.completed_at=new Date().toISOString();const r=await supabase.from('appointments').update(data).eq('id',row.id).eq('flow',row.flow);if(r.error)setError(r.error.message);else await refresh();}
 async function convertOperation(row:Row){if(!supabase||!org||!branchId)return;if(!row.patient_id||row.flow!=='completed'){setError('تحويل العمليات متاح فقط بعد اكتمال الكشف وتسجيل المريض في ملف المرضى.');return;}const p=patients.find(x=>x.id===row.patient_id);if(!p){setError('لازم المريض يكون مسجل في ملف المرضى قبل تحويله لعملية');return;}setForm({patient_id:p.id,appointment_id:row.id,scheduled_at:row.scheduled_at,procedure_type:'hair_transplant'});setSelectedPatient(row);setModal('operation');}
 async function saveOperation(e:any){e.preventDefault();if(!supabase||!org||!branchId)return;const patient=patients.find(p=>p.id===form.patient_id);if(!patient){setError('اختر المريض');return;}const total=Number(form.total_amount||0),deposit=Number(form.deposit_amount||0);if(deposit>total){setError('المقدم لا يمكن أن يكون أكبر من الإجمالي');return;}setBusy(true);const op=await supabase.from('operations').insert({organization_id:org,branch_id:branchId,patient_id:patient.id,appointment_id:form.appointment_id||null,scheduled_at:form.scheduled_at?new Date(form.scheduled_at).toISOString():null,procedure_type:form.procedure_type||'hair_transplant',total_amount:total,deposit_amount:deposit,planned_grafts:form.planned_grafts?Number(form.planned_grafts):null,extractor_doctor_id:form.extractor_doctor_id||null,opening_doctor_ids:form.opening_doctor_ids||[],opening_doctor_names:form.opening_doctor_names||null,implant_doctor_name:form.implant_doctor_name||null,notes:form.notes||null,created_by:profile.id}).select('*').single();if(op.error){setError(op.error.message);setBusy(false);return;}if(form.phone||form.national_id){const priv=await supabase.from('operation_private_details').insert({operation_id:op.data.id,organization_id:org,branch_id:branchId,phone:form.phone||null,national_id:form.national_id||null});if(priv.error)setError('تم إنشاء العملية لكن تعذر حفظ بيانات التواصل: '+priv.error.message);}if(deposit>0){const fin=await supabase.from('financial_transactions').insert({organization_id:org,branch_id:branchId,direction:'income',description:`مقدم عملية زراعة - ${patient.full_name}`,amount:deposit,payment_method:form.deposit_payment_method||'cash',patient_id:patient.id,operation_id:op.data.id,created_by:profile.id});if(fin.error)setError('تم إنشاء العملية لكن تعذر تسجيل المقدم ماليًا: '+fin.error.message);}if(form.appointment_id){const ap=await supabase.from('appointments').update({flow:'converted_to_operation',converted_to_operation:true}).eq('id',form.appointment_id);if(ap.error)setError(ap.error.message);}const labs=String(form.labs||'').split(',').map(s=>s.trim()).filter(Boolean);if(labs.length){const l=await supabase.from('operation_labs').insert(labs.map(test_name=>({organization_id:org,branch_id:branchId,operation_id:op.data.id,test_name,required:true})));if(l.error)setError('تم إنشاء العملية ولكن تعذر تسجيل التحاليل: '+l.error.message);}setModal('');setBusy(false);await refresh();}
 async function addFinance(e:any){e.preventDefault();if(!supabase||!org||!branchId)return;const r=await supabase.from('financial_transactions').insert({organization_id:org,branch_id:branchId,direction:form.direction,description:form.description,amount:Number(form.amount),payment_method:form.payment_method,paid_at:form.paid_at?new Date(form.paid_at).toISOString():new Date().toISOString(),patient_id:form.patient_id||null,created_by:profile.id});if(r.error)setError(r.error.message);else{setModal('');await refresh();}}
 async function saveVisit(e:any){e.preventDefault();if(!supabase||!org||!branchId)return;const patient=patients.find(p=>p.id===form.patient_id);if(!patient){setError('اختر المريض');return;}const r=await supabase.from('visits').insert({organization_id:org,branch_id:branchId,patient_id:patient.id,doctor_id:profile.id,visited_at:form.visited_at?new Date(form.visited_at).toISOString():new Date().toISOString(),complaint:form.complaint||null,diagnosis:form.diagnosis||null,examination:form.examination||null,treatment_plan:form.treatment_plan||null,prescription:form.prescription||null,notes:form.notes||null,created_by:profile.id});if(r.error)setError(r.error.message);else{setModal('');await refresh();}}
 async function addSchedule(e:any){e.preventDefault();if(!supabase||!org||!branchId)return;const r=await supabase.from('staff_schedules').insert({organization_id:org,branch_id:branchId,staff_profile_id:form.staff_profile_id,weekday:Number(form.weekday),start_time:form.start_time||'09:00',end_time:form.end_time||'17:00',active:true,title:form.title||null});if(r.error)setError(r.error.message);else{setModal('');await refresh();}}
 async function saveUserPermissions(e:any){e.preventDefault();if(!supabase||!isAdmin||!selectedPatient)return;setBusy(true);const r=await supabase.from('profiles').update({permissions:{...(selectedPatient.permissions||{}),modules:Array.isArray(form.permissions?.modules)?form.permissions.modules:[]}}).eq('id',selectedPatient.id);if(r.error)setError(r.error.message);else{setModal('');await refresh();}setBusy(false);}
 async function saveUser(e:any){e.preventDefault();if(!supabase||!isAdmin){setError('Admin فقط');return;}const session=await supabase.auth.getSession();const token=session.data.session?.access_token;if(!token){setError('انتهت الجلسة');return;}const response=await fetch('/api/admin/users',{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`},body:JSON.stringify(form)});const result=await response.json();if(!response.ok){const diagnostic=result.diagnostic?`\nDiagnostic: ${typeof result.diagnostic==='string'?result.diagnostic:JSON.stringify(result.diagnostic)}`:'';setError((result.error||'فشل إنشاء المستخدم')+diagnostic);return;}setModal('');await refresh();}
 async function savePatientEdit(e:any){e.preventDefault();if(!supabase||!selectedPatient)return;const updated=await supabase.from('patients').update({full_name:String(form.full_name||'').trim(),age:form.age?Number(form.age):null,gender:form.gender||null,acquisition_source:form.acquisition_source||null,notes:form.notes||null}).eq('id',selectedPatient.id);if(updated.error){setError(updated.error.message);return;}if(patientPrivate){const pr=await supabase.from('patient_private_details').update({phone:form.phone||null,national_id:form.national_id||null,address:form.address||null}).eq('patient_id',selectedPatient.id);if(pr.error){setError(pr.error.message);return;}}else if(form.phone||form.national_id||form.address){const pr=await supabase.from('patient_private_details').insert({patient_id:selectedPatient.id,organization_id:org,branch_id:branchId,phone:form.phone||null,national_id:form.national_id||null,address:form.address||null});if(pr.error){setError(pr.error.message);return;}}setModal('');await refresh();}
 async function showPatientDetails(p:Row){
  setSelectedPatient(p);setModal('patient-details');setPatientPrivate(null);setPatientVisits([]);setPatientImages([]);
  if(!supabase)return;
  if(['admin','reception'].includes(profile?.role)){
   const pr=await supabase.from('patient_private_details').select('*').eq('patient_id',p.id).maybeSingle();setPatientPrivate(pr.data||null);
  }
  const v=await supabase.from('visits').select('*').eq('patient_id',p.id).order('visited_at',{ascending:false});setPatientVisits(v.data||[]);
  const imgs=await supabase.from('patient_images').select('*').eq('patient_id',p.id).order('captured_at',{ascending:false});
  const signed=await Promise.all((imgs.data||[]).map(async (i:Row)=>{const result=await supabase!.storage.from('clinic-patient-images').createSignedUrl(i.storage_path,3600);return {...i,url:result.data?.signedUrl||''};}));
  setPatientImages(signed);
 }
 async function uploadImage(e:any){
  e.preventDefault();const file=e.target.files?.[0] as File|undefined;
  if(!file||!supabase||!selectedPatient||!org||!branchId)return;
  const watermarked=await watermarkFile(file);const path=`${org}/${branchId}/${selectedPatient.id}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;
  const up=await supabase.storage.from('clinic-patient-images').upload(path,watermarked,{contentType:file.type||'image/jpeg'});
  if(up.error){setError(up.error.message);return;}
  const record=await supabase.from('patient_images').insert({organization_id:org,branch_id:branchId,patient_id:selectedPatient.id,storage_path:path,captured_at:new Date().toISOString(),uploaded_by:profile.id,watermark_applied:true});
  if(record.error)setError(record.error.message);else await showPatientDetails(selectedPatient);
 }
 const startOfWeek=(offset:number)=>{const now=new Date();const day=(now.getDay()+6)%7;now.setDate(now.getDate()-day+offset*7);now.setHours(0,0,0,0);return now;};
 const weekStart=startOfWeek(weekOffset);const weekEnd=new Date(weekStart);weekEnd.setDate(weekEnd.getDate()+7);
 const weekDates=Array.from({length:7},(_,i)=>{const d=new Date(weekStart);d.setDate(d.getDate()+i);return d;});
 const reportStart=new Date(weekStart);const reportEnd=new Date(weekEnd);if(reportPeriod==='day'){reportStart.setTime(new Date().setHours(0,0,0,0));reportStart.setDate(reportStart.getDate()+weekOffset);reportEnd.setTime(reportStart.getTime()+86400000);}else if(reportPeriod==='month'){reportStart.setTime(new Date().setHours(0,0,0,0));reportStart.setDate(1);reportStart.setMonth(reportStart.getMonth()+weekOffset);reportEnd.setTime(reportStart.getTime());reportEnd.setMonth(reportEnd.getMonth()+1);}const reportRows=rows.filter(r=>{const d=new Date(r.paid_at||r.created_at||0);return d>=reportStart&&d<reportEnd;});
 const reportIncome=reportRows.filter(r=>r.direction==='income').reduce((a,r)=>a+Number(r.amount||0),0);const reportExpenses=reportRows.filter(r=>r.direction==='expense').reduce((a,r)=>a+Number(r.amount||0),0);
 return <div className="app-shell" dir="rtl"><aside className="side"><div className="logo-block"><img src="/hair-clinic-logo.jpg" alt="DHC Hair Experts"/><div><strong>HAIR CLINIC OS</strong><small>نظام إدارة العيادة</small></div></div><div className="nav-caption">القائمة الرئيسية</div><nav>{visibleNav.map(([key,icon,label])=><button key={key} className={moduleKey===key?'selected':''} onClick={()=>{setModuleKey(key);setSearch('');setError('');}}><span className="nav-icon">{icon}</span><span>{label}</span></button>)}</nav><div className="sidebar-bottom">DHC HAIR EXPERTS<br/><span>Clinic Operations</span></div></aside>
 <main className="workspace"><header className="topbar"><div className="crumb">Hair Clinic OS <span>/</span> {currentModule}</div><div className="userbar"><select className="branch-select" value={branchId} disabled={!isAdmin} onChange={e=>setBranchId(e.target.value)}>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><span className="user-dot">{(profile?.full_name||'م').slice(0,1)}</span><div><b>{profile?.full_name||'المستخدم'}</b><small>{profile?.role||'عضو فريق'}</small></div><button onClick={logout} className="logout-btn">تسجيل الخروج</button></div></header>
 <div className="page-area"><div className="heading-row"><div><h1>{currentModule}</h1><p>{branch?.name||'اختر الفرع'} · بيانات تشغيلية متصلة بقاعدة البيانات</p></div>{moduleKey!=='home'&&moduleKey!=='reports'&&moduleKey!=='users'&&moduleKey!=='finance'&&<button className="add-btn" onClick={()=>openModal(moduleKey==='patients'?'patient':moduleKey==='appointments'?'appointment':moduleKey==='operations'?'operation':moduleKey==='visits'?'visit':moduleKey==='staff'?'schedule':moduleKey==='users'?'user':'finance')}>＋ إضافة جديد</button>}</div>
 {error&&<div className="error">{error}<button className="row-action" onClick={()=>setError('')}>إغلاق</button></div>}
 {moduleKey==='home'&&<><div className="overview-grid">{[['المرضى',counts.patients],['المواعيد',counts.appointments],['عمليات الزراعة',counts.operations],['الزيارات',counts.visits]].map(([label,count])=><div className="stat-card" key={label}><div className="stat-label">{label}</div><div className="stat-value">{count??'—'}</div><div className="stat-foot">الفرع الحالي · مباشر</div></div>)}</div><section className="white-card"><h2>الوحدات التشغيلية</h2><div className="module-grid">{visibleNav.filter(x=>x[0]!=='home').map(([k,i,n])=><button key={k} onClick={()=>setModuleKey(k)}><span>{i}</span><b>{n}</b><small>فتح الوحدة ←</small></button>)}</div></section></>}
 {moduleKey==='doctor'&&<section className="white-card"><div className="toolbar"><button className="row-action" onClick={()=>setWeekOffset(weekOffset-1)}>الأسبوع السابق</button><b>جدول الدكتور · {weekStart.toLocaleDateString('ar-EG')}</b><button className="row-action" onClick={()=>setWeekOffset(weekOffset+1)}>الأسبوع التالي</button></div><div className="week-grid">{weekDates.map((d,i)=><div className="week-day" key={i}><h3>{dayNames[(i+1)%7]}</h3><small>{d.toLocaleDateString('ar-EG')}</small>{((i+1)%7===5)?<div className="schedule-chip">إجازة الجمعة</div>:<>{doctorScheduleRows.filter(s=>Number(s.weekday)===((i+1)%7)&&s.staff_profile_id===targetDoctorId).map(s=><div className="schedule-chip" key={'sch-'+s.id}>متاح · {s.start_time?.slice(0,5)}–{s.end_time?.slice(0,5)}</div>)}{filtered.filter(a=>{const dt=new Date(a.scheduled_at);return dt.toDateString()===d.toDateString()&&a.doctor_id===targetDoctorId;}).map(a=><div className="schedule-chip" key={a.id}>{a.patient_name}<small>{new Date(a.scheduled_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})} · {a.service_name||a.kind}</small></div>)}</>}</div>)}</div><p className="muted">الجدول يعرض الأيام المتاحة من جدول الفريق ومواعيد الدكتور المرتبطة. الجمعة إجازة ثابتة في العرض.</p></section>}
 {moduleKey==='appointments'&&<section className="white-card data-card"><div className="toolbar"><input placeholder="بحث بالاسم أو الخدمة أو الوقت" value={search} onChange={e=>setSearch(e.target.value)}/><span>{filtered.length} موعد</span></div><div className="table-wrap"><table><thead><tr><th>المريض</th><th>الخدمة</th><th>السعر</th><th>التوقيت (دقيقة)</th><th>الوصول</th><th>مسار الموعد</th><th>الإجراءات</th></tr></thead><tbody>{filtered.map(r=><tr key={r.id}><td>{r.patient_name}</td><td>{r.service_name||r.kind}</td><td>{money(r.service_fee??r.fee)}</td><td>{dateTime(r.scheduled_at)}</td><td>{r.arrival_source||'—'}</td><td>{flowLabels[r.flow]||r.flow}</td><td className="actions">{r.flow==='booked'&&<button className="row-action" onClick={()=>changeAppointment(r,'arrived')}>وصل</button>}{r.flow==='arrived'&&<button className="row-action" onClick={()=>changeAppointment(r,'with_doctor')}>دخل عند الدكتور</button>}{r.flow==='with_doctor'&&<button className="row-action" onClick={()=>changeAppointment(r,'completed')}>اكتمل</button>}{r.flow==='completed'&&<button className="row-action" onClick={()=>convertOperation(r)}>تحويل للعمليات</button>}</td></tr>)}</tbody></table>{!filtered.length&&<div className="empty">لا توجد مواعيد في هذا الفرع</div>}</div></section>}
 {moduleKey==='patients'&&<section className="white-card data-card"><div className="toolbar"><input placeholder="بحث بالاسم أو رقم المريض" value={search} onChange={e=>setSearch(e.target.value)}/><span>{filtered.length} مريض</span></div><div className="table-wrap"><table><thead><tr><th>رقم الملف</th><th>الاسم</th><th>العمر</th><th>مصدر الوصول</th><th>تاريخ التسجيل</th><th>التفاصيل</th></tr></thead><tbody>{filtered.map(r=><tr key={r.id}><td>{r.patient_number||'—'}</td><td>{r.full_name}</td><td>{r.age??'—'}</td><td>{r.acquisition_source||'—'}</td><td>{dateTime(r.created_at)}</td><td><button className="row-action" onClick={()=>showPatientDetails(r)}>فتح الملف</button></td></tr>)}</tbody></table>{!filtered.length&&<div className="empty">لا توجد ملفات</div>}</div></section>}
 {moduleKey==='operations'&&<section className="white-card data-card"><div className="toolbar"><input placeholder="بحث بالمريض أو الفريق" value={search} onChange={e=>setSearch(e.target.value)}/><span>{filtered.length} عملية</span></div><div className="table-wrap"><table><thead><tr><th>المريض</th><th>تاريخ العملية</th><th>الإجمالي</th><th>المقدم</th><th>المتبقي</th><th>التحاليل / الفريق</th></tr></thead><tbody>{filtered.map(r=><tr key={r.id}><td>{patients.find(p=>p.id===r.patient_id)?.full_name||r.patient_id}</td><td>{dateTime(r.scheduled_at)}</td><td>{money(r.total_amount)}</td><td>{money(r.deposit_amount)}</td><td>{money(Number(r.total_amount||0)-Number(r.deposit_amount||0))}</td><td><button className="row-action" onClick={()=>{setSelectedPatient(r);setModal('operation-details')}}>التفاصيل</button></td></tr>)}</tbody></table></div></section>}
 {moduleKey==='visits'&&<section className="white-card data-card"><div className="toolbar"><input placeholder="بحث" value={search} onChange={e=>setSearch(e.target.value)}/><span>{filtered.length} زيارة</span></div><div className="table-wrap"><table><thead><tr><th>المريض</th><th>التاريخ</th><th>الشكوى</th><th>التشخيص</th><th>الروشتة</th></tr></thead><tbody>{filtered.map(r=><tr key={r.id}><td>{patients.find(p=>p.id===r.patient_id)?.full_name||r.patient_id}</td><td>{dateTime(r.visited_at)}</td><td>{r.complaint||'—'}</td><td>{r.diagnosis||'—'}</td><td>{r.prescription||'—'}</td></tr>)}</tbody></table></div></section>}
 {(moduleKey==='staff'||moduleKey==='users')&&<section className="white-card data-card"><div className="toolbar"><span>{moduleKey==='users'?'إدارة المستخدمين والصلاحيات · Admin فقط':'جدول الفريق الأسبوعي · الجمعة إجازة افتراضية لدكتور عبد الرحمن'}</span>{moduleKey==='staff'&&<button className="row-action" onClick={()=>openModal('schedule')}>＋ إضافة جدول</button>}{moduleKey==='users'&&isAdmin&&<button className="row-action" onClick={()=>openModal('user')}>＋ إنشاء مستخدم</button>}</div>{moduleKey==='staff'&&<div className="week-grid">{weekDates.map((d,i)=><div className="week-day" key={i}><h3>{dayNames[(i+1)%7]}</h3><small>{d.toLocaleDateString('ar-EG')}</small>{rows.filter(r=>Number(r.weekday)===((i+1)%7)).map(r=><div className="schedule-chip" key={r.id}>{staff.find(s=>s.id===r.staff_profile_id)?.full_name||r.title||'عضو فريق'}<small>{r.start_time?.slice(0,5)} - {r.end_time?.slice(0,5)}</small></div>)}</div>)}</div>}{moduleKey==='staff'&&<div className="table-wrap"><table><thead><tr><th>الطبيب / عضو الفريق</th><th>اليوم</th><th>من</th><th>إلى</th></tr></thead><tbody>{filtered.map(r=><tr key={r.id}><td>{staff.find(s=>s.id===r.staff_profile_id)?.full_name||r.title||r.staff_profile_id}</td><td>{dayNames[r.weekday]}</td><td>{r.start_time?.slice(0,5)}</td><td>{r.end_time?.slice(0,5)}</td></tr>)}</tbody></table></div>}{moduleKey==='users'&&<div className="table-wrap"><table><thead><tr><th>الاسم</th><th>الدور</th><th>الفرع</th><th>Active</th><th>الصلاحيات</th></tr></thead><tbody>{rows.map(u=><tr key={u.id}><td>{u.full_name}</td><td>{u.role}</td><td>{branches.find(b=>b.id===u.branch_id)?.name||'—'}</td><td>{u.active?'نعم':'لا'}</td><td><button className="row-action" onClick={()=>{setSelectedPatient(u);setForm({role:u.role,permissions:{modules:Array.isArray(u.permissions?.modules)?[...u.permissions.modules]:[...(roleModules[u.role]||['home'])]}});setModal('permissions')}}>تعديل الوصول</button></td></tr>)}</tbody></table></div>}</section>}
 {moduleKey==='finance'&&<section className="white-card data-card"><div className="toolbar"><input placeholder="بحث في البيان" value={search} onChange={e=>setSearch(e.target.value)}/><span>{filtered.length} حركة مالية</span><button className="add-btn" onClick={()=>openModal('finance')}>＋ تسجيل إيراد / مصروف</button></div><div className="overview-grid finance-metrics"><div className="stat-card"><div className="stat-label">الإيرادات</div><div className="stat-value">{money(rows.filter(r=>r.direction==='income').reduce((s,r)=>s+Number(r.amount),0))}</div></div><div className="stat-card"><div className="stat-label">المصروفات</div><div className="stat-value">{money(rows.filter(r=>r.direction==='expense').reduce((s,r)=>s+Number(r.amount),0))}</div></div><div className="stat-card"><div className="stat-label">الصافي</div><div className="stat-value">{money(rows.reduce((s,r)=>s+(r.direction==='income'?Number(r.amount):-Number(r.amount)),0))}</div></div></div><div className="table-wrap"><table><thead><tr><th>النوع</th><th>البيان</th><th>المبلغ</th><th>طريقة الدفع</th><th>التاريخ</th></tr></thead><tbody>{filtered.map(r=><tr key={r.id}><td>{r.direction==='income'?'إيراد':'مصروف'}</td><td>{r.description}</td><td>{money(r.amount)}</td><td>{paymentLabels[r.payment_method]||r.payment_method}</td><td>{dateTime(r.paid_at)}</td></tr>)}</tbody></table></div></section>}
 {moduleKey==='reports'&&<section className="white-card"><div className="toolbar"><button className="row-action" onClick={()=>setWeekOffset(weekOffset-1)}>الفترة السابقة</button><select value={reportPeriod} onChange={e=>setReportPeriod(e.target.value as any)}><option value="day">يومي</option><option value="week">أسبوعي</option><option value="month">شهري</option></select><b>{reportStart.toLocaleDateString('ar-EG')} — {new Date(reportEnd.getTime()-1).toLocaleDateString('ar-EG')}</b><button className="row-action" onClick={()=>setWeekOffset(weekOffset+1)}>الفترة التالية</button><button className="row-action" onClick={()=>window.print()}>طباعة التقرير</button></div><div className="overview-grid"><div className="stat-card"><div className="stat-label">إيرادات الفترة</div><div className="stat-value">{money(reportIncome)}</div></div><div className="stat-card"><div className="stat-label">مصروفات الفترة</div><div className="stat-value">{money(reportExpenses)}</div></div><div className="stat-card"><div className="stat-label">الصافي</div><div className="stat-value">{money(reportIncome-reportExpenses)}</div></div></div><div className="overview-grid finance-metrics">{Object.entries(paymentLabels).map(([method,label])=><div className="stat-card" key={method}><div className="stat-label">{label}</div><div className="stat-value">{money(reportRows.filter(r=>r.direction==='income'&&r.payment_method===method).reduce((sum,r)=>sum+Number(r.amount),0))}</div></div>)}</div><div className="table-wrap"><table><thead><tr><th>النوع</th><th>البيان</th><th>المبلغ</th><th>طريقة الدفع</th><th>التاريخ</th></tr></thead><tbody>{reportRows.map(r=><tr key={r.id}><td>{r.direction==='income'?'إيراد':'مصروف'}</td><td>{r.description}</td><td>{money(r.amount)}</td><td>{paymentLabels[r.payment_method]}</td><td>{dateTime(r.paid_at)}</td></tr>)}</tbody></table></div></section>}
 </div></main>
 {modal&&<div className="modal-backdrop" onClick={()=>setModal('')}><div className="modal" onClick={e=>e.stopPropagation()}><h2>{modal==='patient'?'تسجيل مريض':modal==='appointment'?'حجز موعد فوري':modal==='operation'?'تسجيل عملية زراعة شعر':modal==='visit'?'تسجيل زيارة طبية':modal==='schedule'?'إضافة جدول أسبوعي':modal==='finance'?'إضافة حركة مالية':modal==='patient-details'?'ملف المريض':modal==='operation-details'?'تفاصيل العملية':modal==='patient-edit'?'تعديل ملف المريض':modal==='user'?'إنشاء مستخدم جديد':modal==='permissions'?'تعديل صلاحيات المستخدم':modal==='patient-edit'?'تعديل ملف المريض':''}</h2>
 {modal==='patient'&&<form onSubmit={savePatient}><label>الاسم الكامل<input required value={form.full_name||''} onChange={e=>setForm({...form,full_name:e.target.value})}/></label><label>العمر<input type="number" min="0" max="125" value={form.age||''} onChange={e=>setForm({...form,age:e.target.value})}/></label><label>رقم الهاتف<input value={form.phone||''} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>الرقم القومي<input value={form.national_id||''} onChange={e=>setForm({...form,national_id:e.target.value})}/></label><label>العنوان<input value={form.address||''} onChange={e=>setForm({...form,address:e.target.value})}/></label><label>النوع<select value={form.gender||''} onChange={e=>setForm({...form,gender:e.target.value})}><option value="">—</option><option>ذكر</option><option>أنثى</option></select></label><label>طريقة الوصول<input placeholder="ترشيح / إعلان / سوشيال ميديا" value={form.acquisition_source||''} onChange={e=>setForm({...form,acquisition_source:e.target.value})}/></label><label className="span2">ملاحظات<textarea value={form.notes||''} onChange={e=>setForm({...form,notes:e.target.value})}/></label><ModalActions close={()=>setModal('')} busy={busy}/></form>}
 {modal==='appointment'&&<form onSubmit={saveAppointment}><label>المريض<select required value={form.patient_id||''} onChange={e=>setForm({...form,patient_id:e.target.value,patient_name:e.target.value==='__new__'?'':form.patient_name})}><option value="">اختيار مريض مسجل</option><option value="__new__">مريض جديد (تسجيله عند دخول الدكتور)</option>{patients.map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label>{form.patient_id==='__new__'&&<label>اسم المريض<input required value={form.patient_name||''} onChange={e=>setForm({...form,patient_name:e.target.value})}/></label>}<label>رقم الهاتف (اختياري)<input value={form.phone||''} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>الدكتور (اختياري)<select value={form.doctor_id||''} onChange={e=>setForm({...form,doctor_id:e.target.value})}><option value="">غير محدد</option>{staff.filter(s=>s.role==='doctor'&&s.branch_id===branchId).map(s=><option key={s.id} value={s.id}>{s.full_name}</option>)}</select></label><label>الخدمة<select value={form.service||'كشف'} onChange={e=>setForm({...form,service:e.target.value})}>{services.map(s=><option key={s.label}>{s.label}</option>)}</select></label>{['ميزوسربي','بلازما'].includes(form.service)&&<label>نوع الخدمة<select value={form.service_mode||'paid'} onChange={e=>setForm({...form,service_mode:e.target.value})}><option value="paid">مدفوع</option><option value="operation">عملية (مجاني)</option></select></label>}{['بوتكس','تقشير بارد','سكين بوستر'].includes(form.service)&&<label>السعر<input required type="number" min="1" value={form.fee||''} onChange={e=>setForm({...form,fee:e.target.value})}/></label>}<label>العمر<input type="number" min="0" max="125" value={form.age||''} onChange={e=>setForm({...form,age:e.target.value})}/></label><label>طريقة الدفع<select value={form.payment_method||'cash'} onChange={e=>setForm({...form,payment_method:e.target.value})}>{Object.entries(paymentLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>طريقة الوصول<input value={form.arrival_source||''} onChange={e=>setForm({...form,arrival_source:e.target.value})}/></label><label>التاريخ والوقت بالدقيقة<DateTimePicker required value={form.scheduled_at||asLocalInput()} onChange={v=>setForm({...form,scheduled_at:v})} label="موعد المريض"/></label><label>ملاحظات<textarea value={form.notes||''} onChange={e=>setForm({...form,notes:e.target.value})}/></label><ModalActions close={()=>setModal('')} busy={busy}/></form>}
 {modal==='operation'&&<form onSubmit={saveOperation}><label>المريض<select required value={form.patient_id||''} onChange={e=>setForm({...form,patient_id:e.target.value})}><option value="">اختيار مريض</option>{appointmentPatients.map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label><label>موعد العملية<DateTimePicker value={form.scheduled_at||''} onChange={v=>setForm({...form,scheduled_at:v})} label="موعد العملية"/></label><label>إجمالي العملية<input type="number" min="0" required value={form.total_amount||''} onChange={e=>setForm({...form,total_amount:e.target.value})}/></label><label>المقدم<input type="number" min="0" required value={form.deposit_amount||''} onChange={e=>setForm({...form,deposit_amount:e.target.value})}/></label><label>طريقة دفع المقدم<select value={form.deposit_payment_method||'cash'} onChange={e=>setForm({...form,deposit_payment_method:e.target.value})}>{Object.entries(paymentLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>الهاتف<input value={form.phone||''} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>الرقم القومي<input value={form.national_id||''} onChange={e=>setForm({...form,national_id:e.target.value})}/></label><label>عدد البصيلات المتوقع<input type="number" value={form.planned_grafts||''} onChange={e=>setForm({...form,planned_grafts:e.target.value})}/></label><label>دكتور الاقتطاف<select value={form.extractor_doctor_id||''} onChange={e=>setForm({...form,extractor_doctor_id:e.target.value})}><option value="">اختيار</option>{staff.filter(s=>s.role==='doctor').map(s=><option key={s.id} value={s.id}>{s.full_name}</option>)}</select></label><label>دكتور / أطباء التفتيح<input type="text" placeholder="اكتب اسم الدكتور أو أسماء الأطباء" value={form.opening_doctor_names||''} onChange={e=>setForm({...form,opening_doctor_names:e.target.value})}/></label><label>دكتور الزراعة<input value={form.implant_doctor_name||''} onChange={e=>setForm({...form,implant_doctor_name:e.target.value})}/></label><label className="span2">التحاليل (افصل بينها بفاصلة)<input placeholder="CBC, PT, PTT, ..." value={form.labs||''} onChange={e=>setForm({...form,labs:e.target.value})}/></label><label className="span2">ملاحظات<textarea value={form.notes||''} onChange={e=>setForm({...form,notes:e.target.value})}/></label><ModalActions close={()=>setModal('')} busy={busy}/></form>}
 {modal==='visit'&&<form onSubmit={saveVisit}><label>المريض<select required value={form.patient_id||''} onChange={e=>setForm({...form,patient_id:e.target.value})}><option value="">اختيار</option>{patients.map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label><label>التاريخ<DateTimePicker value={form.visited_at||asLocalInput()} onChange={v=>setForm({...form,visited_at:v})} label="تاريخ الزيارة"/></label><label>الشكوى<textarea value={form.complaint||''} onChange={e=>setForm({...form,complaint:e.target.value})}/></label><label>الفحص<textarea value={form.examination||''} onChange={e=>setForm({...form,examination:e.target.value})}/></label><label>التشخيص<textarea value={form.diagnosis||''} onChange={e=>setForm({...form,diagnosis:e.target.value})}/></label><label>الخطة العلاجية<textarea value={form.treatment_plan||''} onChange={e=>setForm({...form,treatment_plan:e.target.value})}/></label><label className="span2">الروشتة<textarea value={form.prescription||''} onChange={e=>setForm({...form,prescription:e.target.value})}/></label><ModalActions close={()=>setModal('')} busy={busy}/></form>}
 {modal==='finance'&&<form onSubmit={addFinance}><label>نوع الحركة<select value={form.direction||'income'} onChange={e=>setForm({...form,direction:e.target.value})}><option value="income">إيراد</option><option value="expense">مصروف</option></select></label><label>البيان<input required value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></label><label>المبلغ<input required type="number" min="1" value={form.amount||''} onChange={e=>setForm({...form,amount:e.target.value})}/></label><label>طريقة الدفع<select value={form.payment_method||'cash'} onChange={e=>setForm({...form,payment_method:e.target.value})}>{Object.entries(paymentLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>المريض (اختياري)<select value={form.patient_id||''} onChange={e=>setForm({...form,patient_id:e.target.value})}><option value="">غير مرتبط</option>{patients.map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></label><label>التاريخ<DateTimePicker value={form.paid_at||asLocalInput()} onChange={v=>setForm({...form,paid_at:v})} label="تاريخ الحركة المالية"/></label><ModalActions close={()=>setModal('')} busy={busy}/></form>}
 {modal==='schedule'&&<form onSubmit={addSchedule}><label>الطبيب / الفريق<select required value={form.staff_profile_id||''} onChange={e=>setForm({...form,staff_profile_id:e.target.value})}><option value="">اختيار</option>{staff.map(s=><option key={s.id} value={s.id}>{s.full_name} ({s.role})</option>)}</select></label><label>اليوم<select value={form.weekday||'0'} onChange={e=>setForm({...form,weekday:e.target.value})}>{dayNames.map((d,i)=><option key={i} value={i}>{d}</option>)}</select></label><label>من<input type="time" value={form.start_time||'09:00'} onChange={e=>setForm({...form,start_time:e.target.value})}/></label><label>إلى<input type="time" value={form.end_time||'17:00'} onChange={e=>setForm({...form,end_time:e.target.value})}/></label><label className="span2">مسمى / ملاحظة<input value={form.title||''} onChange={e=>setForm({...form,title:e.target.value})}/></label><ModalActions close={()=>setModal('')} busy={busy}/></form>}
 {modal==='user'&&<form onSubmit={saveUser}><label>الاسم الكامل<input required value={form.full_name||''} onChange={e=>setForm({...form,full_name:e.target.value})}/></label><label>البريد (للدخول)<input required type="email" value={form.email||''} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>كلمة المرور<input required type="password" minLength={8} value={form.password||''} onChange={e=>setForm({...form,password:e.target.value})}/></label><label>الدور<select value={form.role||'reception'} onChange={e=>{const role=e.target.value;setForm({...form,role,permissions:{...(form.permissions||{}),modules:[...(roleModules[role]||['home'])]}})}}><option value="reception">سكرتارية</option><option value="doctor">دكتور</option><option value="hair_team">فريق زراعة</option><option value="finance">حسابات</option><option value="admin">Admin</option></select></label><label>الفرع<select required value={form.branch_id||''} onChange={e=>setForm({...form,branch_id:e.target.value})}><option value="">اختر الفرع</option>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><div className="span2 permission-box"><b>صلاحيات الوحدات لهذا المستخدم</b><small>اختار الأقسام التي يقدر يفتحها. الصلاحيات المحددة هنا هي الأقسام المتاحة لهذا المستخدم داخل دوره.</small><div className="permission-grid">{nav.filter(([k])=>k!=='home'&&k!=='users'&&(roleModules[form.role||'reception']||[]).includes(k)).map(([key,icon,label])=><label key={key} className="permission-option"><input type="checkbox" checked={(form.permissions?.modules||[]).includes(key)} onChange={e=>{const current=Array.isArray(form.permissions?.modules)?form.permissions.modules:[];const next=e.target.checked?[...current,key]:current.filter((x:string)=>x!==key);setForm({...form,permissions:{...(form.permissions||{}),modules:next}});}}/><span>{label}</span></label>)}</div></div><ModalActions close={()=>setModal('')} busy={busy}/></form>}
 {modal==='permissions'&&selectedPatient&&<form onSubmit={saveUserPermissions}><div className="span2 permission-box"><b>صلاحيات {selectedPatient.full_name}</b><small>تقدر تقلل أو تزيد الأقسام المتاحة ضمن الدور الحالي.</small><div className="permission-grid">{nav.filter(([k])=>k!=='home'&&k!=='users'&&(roleModules[selectedPatient.role]||[]).includes(k)).map(([key,icon,label])=><label key={key} className="permission-option"><input type="checkbox" checked={(form.permissions?.modules||[]).includes(key)} onChange={e=>{const current=Array.isArray(form.permissions?.modules)?form.permissions.modules:[];const next=e.target.checked?[...current,key]:current.filter((x:string)=>x!==key);setForm({...form,permissions:{...(form.permissions||{}),modules:next}});}}/><span>{label}</span></label>)}</div></div><ModalActions close={()=>setModal('')} busy={busy}/></form>}
 {modal==='patient-edit'&&selectedPatient&&<form onSubmit={savePatientEdit}><label>الاسم<input required value={form.full_name||''} onChange={e=>setForm({...form,full_name:e.target.value})}/></label><label>العمر<input type="number" value={form.age||''} onChange={e=>setForm({...form,age:e.target.value})}/></label><label>الهاتف<input value={form.phone||''} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>الرقم القومي<input value={form.national_id||''} onChange={e=>setForm({...form,national_id:e.target.value})}/></label><label>العنوان<input value={form.address||''} onChange={e=>setForm({...form,address:e.target.value})}/></label><label>النوع<select value={form.gender||''} onChange={e=>setForm({...form,gender:e.target.value})}><option value="">—</option><option>ذكر</option><option>أنثى</option></select></label><label>مصدر الوصول<input value={form.acquisition_source||''} onChange={e=>setForm({...form,acquisition_source:e.target.value})}/></label><label className="span2">ملاحظات<textarea value={form.notes||''} onChange={e=>setForm({...form,notes:e.target.value})}/></label><ModalActions close={()=>setModal('')} busy={busy}/></form>}
 {modal==='patient-details'&&selectedPatient&&<div className="patient-detail"><p><b>ملف:</b> {selectedPatient.full_name} · #{selectedPatient.patient_number}</p><p><b>العمر:</b> {selectedPatient.age||'—'} · <b>مصدر الوصول:</b> {selectedPatient.acquisition_source||'—'}</p>{patientPrivate&&<div className="private-box"><b>بيانات الإدارة</b><p>الهاتف: {patientPrivate.phone||'—'}</p><p>العنوان: {patientPrivate.address||'—'}</p><p>الرقم القومي: {patientPrivate.national_id||'—'}</p></div>}<h3>سجل الزيارات</h3>{patientVisits.map(v=><div className="detail-line" key={v.id}><b>{dateTime(v.visited_at)}</b><p>{v.complaint||'—'}</p><p>التشخيص: {v.diagnosis||'—'}</p><p>الروشتة: {v.prescription||'—'}</p></div>)}<h3>صور المريض (مرتبة بالتاريخ)</h3><label className="upload-label">رفع صورة مع علامة شعار المركز<input type="file" accept="image/*" onChange={uploadImage}/></label><div className="patient-image-grid">{patientImages.map(i=><div key={i.id}><img src={i.url} alt="patient record"/><small>{dateTime(i.captured_at)}</small></div>)}</div>{['admin','reception'].includes(profile?.role)&&<button className="row-action" onClick={()=>{setForm({...selectedPatient,...(patientPrivate||{})});setModal('patient-edit')}}>تعديل البيانات</button>}<button className="cancel" onClick={()=>setModal('')}>إغلاق</button></div>}
 {modal==='operation-details'&&selectedPatient&&<div className="patient-detail"><p>عملية: {patients.find(p=>p.id===selectedPatient.patient_id)?.full_name||selectedPatient.patient_id}</p><p>المبلغ: {money(selectedPatient.total_amount)} · المقدم: {money(selectedPatient.deposit_amount)} · المتبقي: {money(Number(selectedPatient.total_amount)-Number(selectedPatient.deposit_amount))}</p><p>دكتور / أطباء التفتيح: {selectedPatient.opening_doctor_names||'—'}</p><p>دكتور الزراعة: {selectedPatient.implant_doctor_name||'—'}</p><button className="row-action" onClick={async()=>{if(!supabase)return;const labs=await supabase.from('operation_labs').select('*').eq('operation_id',selectedPatient.id);setForm({labs_data:labs.data||[]});setModal('operation-labs')}}>التحاليل</button></div>}
 {modal==='operation-labs'&&<div className="patient-detail">{(form.labs_data||[]).map((lab:Row)=><div className="detail-line" key={lab.id}><span>{lab.test_name}</span><span>{lab.status==='received'?'تم الاستلام':'لم يتم الاستلام'}</span>{lab.status!=='received'&&<button className="row-action" onClick={async()=>{const r=await supabase!.from('operation_labs').update({status:'received',received_at:new Date().toISOString(),received_by:profile.id}).eq('id',lab.id);if(r.error)setError(r.error.message);else setForm({...form,labs_data:form.labs_data.map((x:Row)=>x.id===lab.id?{...x,status:'received'}:x)});}}>تم الاستلام</button>}</div>)}{['admin','reception'].includes(profile?.role)&&<button className="row-action" onClick={()=>{setForm({...selectedPatient,...(patientPrivate||{})});setModal('patient-edit')}}>تعديل البيانات</button>}<button className="cancel" onClick={()=>setModal('')}>إغلاق</button></div>}
 </div></div>}
 </div>
}
function ModalActions({close,busy}:{close:()=>void;busy:boolean}){return <div className="modal-actions"><button type="button" className="cancel" onClick={close}>إلغاء</button><button type="submit" className="add-btn" disabled={busy}>{busy?'جارٍ الحفظ…':'حفظ'}</button></div>}
async function watermarkFile(file:File):Promise<File>{try{if(!file.type.startsWith('image/'))return file;const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;const ctx=canvas.getContext('2d');if(!ctx)return file;ctx.drawImage(bitmap,0,0);const logo=new Image();logo.src='/hair-clinic-logo.jpg';await new Promise<void>(resolve=>{logo.onload=()=>resolve();logo.onerror=()=>resolve();});const pad=Math.max(16,canvas.width*.02);const logoW=Math.min(canvas.width*.23,320);const logoH=logo.naturalWidth?logoW*(logo.naturalHeight/logo.naturalWidth):logoW*.5;if(logo.naturalWidth){ctx.globalAlpha=.55;ctx.drawImage(logo,canvas.width-logoW-pad,canvas.height-logoH-pad,logoW,logoH);ctx.globalAlpha=1;}else{ctx.fillStyle='rgba(255,255,255,.45)';ctx.font=`bold ${Math.max(14,canvas.width*.025)}px Arial`;ctx.fillText('DHC HAIR EXPERTS',canvas.width-pad-210,canvas.height-pad-12);}const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,file.type==='image/png'?'image/png':'image/jpeg',.92));if(!blob)return file;return new File([blob],file.name,{type:blob.type});}catch{return file;}}
